X, y = data(40, 5, 3)
m = MDS(2, random_state=0, n_init=2, init="random", max_iter=200)
close("mds_m", m.fit_transform(X), mds_m, 1e-6); closes("mds_m_stress", m.stress_, mds_m_stress)
if m.n_iter_ != mds_m_it:
    print("TEST FAILED mds_m_it", m.n_iter_)
m2 = MDS(2, metric_mds=False, random_state=1, n_init=1, init="random", max_iter=100)
close("mds_nm", m2.fit_transform(X), mds_nm, 1e-6); closes("mds_nm_stress", m2.stress_, mds_nm_stress)
if m2.n_iter_ != mds_nm_it:
    print("TEST FAILED mds_nm_it", m2.n_iter_)
m3 = MDS(2, init="classical_mds", max_iter=100)
close("mds_c", m3.fit_transform(X), mds_c, 1e-6); closes("mds_c_stress", m3.stress_, mds_c_stress)
close("cmds", ClassicalMDS(3).fit_transform(X), cmds)
im = Isomap(n_neighbors=6, n_components=2).fit(X)
close("iso_emb", im.embedding_, iso_emb); close("iso_dist", im.dist_matrix_[:3], iso_dist)
close("iso_tr", im.transform(X[:4] + 0.05), iso_tr); closes("iso_err", im.reconstruction_error(), iso_err)
def lle(meth: str, k: int, exp, err: float):
    e = LocallyLinearEmbedding(n_neighbors=k, n_components=2, method=meth, eigen_solver="dense").fit(X)
    close_cols("lle_" + meth, e.embedding_, exp, 2, 1e-4, 1e-6)
    closes("lle_" + meth + "_err", e.reconstruction_error_, err, 1e-4, 1e-9)
lle("standard", 8, lle_standard, lle_standard_err)
lle("modified", 8, lle_modified, lle_modified_err)
lle("ltsa", 8, lle_ltsa, lle_ltsa_err)
lle("hessian", 9, lle_hessian, lle_hessian_err)
e = LocallyLinearEmbedding(n_neighbors=8, n_components=2, eigen_solver="dense").fit(X)
ref = e.embedding_
close_cols("lle_tr", e.transform(X[:3] + 0.05), lle_tr, 2, 1e-4, 1e-6)
close("se_nn", SpectralEmbedding(n_components=2, random_state=0, n_neighbors=8).fit_transform(X), se_nn, 1e-5, 1e-7)
close("se_rbf", SpectralEmbedding(n_components=2, random_state=0, affinity="rbf", gamma=0.2).fit_transform(X), se_rbf, 1e-5, 1e-7)
Z = X[:, :2] + 0.3 * X[:, 2:4]
closes("tw", trustworthiness(X, Z, n_neighbors=5), tw)
closes("tw3", trustworthiness(X, X[:, [0, 2, 4]], n_neighbors=3), tw3)
